// Pixels Tech Lab Trivia Library
// Full question bank for the Stardust Challenge mini trivia.
// Reward weights: 50 = core skill, 75 = deeper knowledge, 100 = online safety.

export type TriviaCategory =
  | 'Blender'
  | 'Tinkercad'
  | 'E-Sports'
  | 'Minecraft Commands'
  | 'Roblox'
  | 'Animation'
  | 'Safety';

export interface TriviaQuestion {
  id: number;
  category: TriviaCategory;
  question: string;
  options: string[];
  correctIndex: number;
  stardustReward: number;
}

let nextId = 1;
const q = (category: TriviaCategory, question: string, options: string[], answer: 'A' | 'B' | 'C' | 'D', stardustReward: number): TriviaQuestion => ({
  id: nextId++,
  category,
  question,
  options,
  correctIndex: { A: 0, B: 1, C: 2, D: 3 }[answer],
  stardustReward,
});

